class Solution:
    def diagonalSort(self, mat: list[list[int]]) -> list[list[int]]:
        ans = [row[:] for row in mat]
        m, n = len(ans), len(ans[0])
        starts = [(r, 0) for r in range(m)] + [(0, c) for c in range(1, n)]
        for sr, sc in starts:
            count = [0] * 101
            r, c = sr, sc
            while r < m and c < n:
                count[ans[r][c]] += 1; r += 1; c += 1
            value = 1
            r, c = sr, sc
            while r < m and c < n:
                while count[value] == 0:
                    value += 1
                ans[r][c] = value
                count[value] -= 1
                r += 1; c += 1
        return ans

